-- +goose Up
-- Запись релиза в журнал (notified_at NULL — бот уведомит админа на старте).
-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.120.0',
  '2026-10-19',
  'Медиатека: музыка по ссылке прямо в нужную папку',
  E'В админке медиатеки у каждой папки есть «📥». Раньше там можно было добавить файлы с компьютера или ZIP-архив, теперь рядом появилось «⬇ По ссылке»: вводите адрес страницы, и в эту самую папку приезжает звук. Папка любая, в том числе вложенная — трек ляжет именно туда, куда вы его метили, а не в корень музыки.\n\nПриезжает только звук и лучший, какой есть на странице: ничего не перекодируется, дорожка переписывается как она есть. Имя файла берётся из названия страницы, а если такое имя уже занято, новый получает «(2)» — ничего не затирается.\n\nСкачивание идёт фоновой задачей: на вкладке «Задачи» видно проценты и можно остановить. Пока качается, в самой папке ничего не появляется — всё складывается в сторонке и переезжает целиком и сразу. Оборвалось на середине — в альбоме чисто, без обломков и обложек.\n\nЕсли в ссылке есть подборка (так получается, когда копируешь адрес из плеера плейлиста), агент спросит: взять один трек или всю подборку. Иначе в альбом молча приехала бы сотня чужих песен.\n\nКачает это yt-dlp — отдельная программа на мини-сервере. Она ломается всякий раз, когда YouTube что-то меняет у себя, и лечится обновлением, поэтому на «Обслуживании» появился её раздел: какая версия стоит и кнопка «⬆ Обновить yt-dlp». Перестало скачиваться — первым делом туда.',
  E'ytdlp.go в агенте: GET /api/admin/fetch (есть ли бинарник и какой версии), POST /api/admin/fetch {url, id, playlist} — задача через общий taskStore, POST /api/admin/fetch/update — «yt-dlp -U». Команда ровно та, которой пользовались руками: -x --audio-quality 0, плюс --embed-metadata, --newline (построчный прогресс), --ignore-config и -o "%(title).150B.%(ext)s" — без хвоста [id], потому что именем дорожки в плеере служит имя файла.\n\nКачаем в os.MkdirTemp внутри кэша и переносим оттуда только файлы с аудио-расширением (transferFile + freeName — те же, что у «собрать альбом»): .part, обложки и .info.json в библиотеку не попадают, а оборванная задача не оставляет в альбоме ничего. Имя от yt-dlp прогоняется через fetchFileName — basename и без ведущих точек: скрытый файл каталог не показывает.\n\nОтмена задачи убивает группу процессов (Setpgid + Kill(-pid)): звук из видео достаёт уже ffmpeg, и без этого «Остановить» оставляло бы его доделывать. Ошибка берётся из строки ERROR: самого yt-dlp, а не из хвоста вывода — иначе в отказе оказывались бы «Extracting URL» и «Downloading webpage». Если часть подборки успела доехать, задача не падает: файлы остаются, причина обрыва уходит в отчёт.\n\nПроверка ссылки строже, чем у «🔗 Ссылки»: cleanURL дописывает схему и пускает «rezka.ag» без https, то есть и случайное слово; здесь дополнительно требуется точка в имени сайта. Перед запуском проверяется место и там, где папка, и в кэше (1 ГБ).\n\nСамого yt-dlp в репозитории нет и быть не может: это 40 МБ, которые живут своими релизами. Путь — ytdlp в конфиге, иначе ~/bin/yt-dlp_linux, ~/bin/yt-dlp, PATH; нет бинарника — страница показывает команду установки (через wget: curl на res-i3 не стоит).\n\nПроверено вживую на res-i3: 10 минут звука (opus 127 кбит/с, 10 МБ) за 25 с, занятое имя получило «(2)», временная папка убрана, «yt-dlp -U» отвечает, отказ на несуществующем видео приходит одной внятной строкой. Плюс восемь тестов на подменённом бинарнике — перенос, занятое имя, отбор только звука, ошибка, частичная подборка, ключи --no-playlist/--yes-playlist, отмена, разбор прогресса.'
);
-- +goose StatementEnd

